import{_ as a,o as t,c as s,a9 as i}from"./chunks/framework.asyjyako.js";const k=JSON.parse('{"title":"Real package examples","description":"","frontmatter":{},"headers":[],"relativePath":"real-packages/index.md","filePath":"real-packages/index.md","lastUpdated":null}'),n={name:"real-packages/index.md"};function r(l,e,h,p,o,d){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="Real-package-examples" tabindex="-1">Real package examples <a class="header-anchor" href="#Real-package-examples" aria-label="Permalink to &quot;Real package examples {#Real-package-examples}&quot;">​</a></h1><p>The examples develop the steps introduced in the manual into larger experiments. Each provides the scripts and saved measurements used by its figures, plus instructions for the terminal and graphical interfaces.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Example</th><th style="text-align:right;">Work performed</th><th style="text-align:right;">What the measurements include</th></tr></thead><tbody><tr><td style="text-align:right;"><a href="./../tutorials/bibliography">Bibliography</a></td><td style="text-align:right;">Import, parse and export bibliography entries</td><td style="text-align:right;">The manual&#39;s example extended to three related packages and nine releases</td></tr><tr><td style="text-align:right;"><a href="./datastructures">DataStructures</a></td><td style="text-align:right;">Construct and use 35 containers, then investigate event processing</td><td style="text-align:right;">70 separate operations across every 0.19 patch, plus a longer historical comparison</td></tr><tr><td style="text-align:right;"><a href="./oxygen">Oxygen</a></td><td style="text-align:right;">Compare seven HTTP features, three application routes and real traffic</td><td style="text-align:right;">Older minor releases and every recent patch; network latency, bytes, packets and throughput have their own figures</td></tr></tbody></table><p>The application workloads share an event stream. It contains a priority, a unique identifier and a category for every event. A fixed seed reproduces the input; an independently computed expected answer checks each workload. This lets you ask whether time is spent processing data or serving the request around it.</p><h2 id="Choose-a-starting-point" tabindex="-1">Choose a starting point <a class="header-anchor" href="#Choose-a-starting-point" aria-label="Permalink to &quot;Choose a starting point {#Choose-a-starting-point}&quot;">​</a></h2><p>Continue with <a href="./../tutorials/bibliography">Bibliography</a> to extend the manual&#39;s example. Choose <a href="./datastructures">DataStructures</a> for CPU and allocation costs, or <a href="./oxygen">Oxygen</a> for request handling and network measurements. Both pages include profiling, diagnostics and commands for the graphical interfaces.</p><p>The <a href="./interfaces">interface reference</a> and <a href="./extensions">tool map</a> collect the shared recipes for later use.</p><p>The documentation build reads saved data and figures; its duration is independent of the time spent running the original benchmarks.</p><h2 id="Get-the-runnable-examples" tabindex="-1">Get the runnable examples <a class="header-anchor" href="#Get-the-runnable-examples" aria-label="Permalink to &quot;Get the runnable examples {#Get-the-runnable-examples}&quot;">​</a></h2><p>The DataStructures and Oxygen scripts are in <a href="https://github.com/Mirage-Interactive-Fr/PerfChecker.jl/tree/release/v1.0.0-rc1/examples/kitchen-sink" target="_blank" rel="noreferrer"><code>examples/kitchen-sink</code></a>. During the release candidate, use a checkout of that branch so the examples and PerfChecker use matching APIs.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release/v1.0.0-rc1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Mirage-Interactive-Fr/PerfChecker.jl.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PerfChecker.jl/examples/kitchen-sink</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core</span></span></code></pre></div><p>Run the DataStructures and Oxygen commands from this directory. The example controller requires Julia 1.12 or newer. <code>setup.jl core</code> activates this directory&#39;s <code>Project.toml</code>, links the checked-out PerfChecker and installs the example dependencies. Optional interfaces get their own <code>.controller/NAME</code> environments when requested.</p><p>Use one Julia compute thread, one GC thread and one BLAS thread, with one precompilation task. Run campaigns sequentially on an otherwise quiet machine. In PowerShell, for example:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JULIA_NUM_THREADS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JULIA_NUM_GC_THREADS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENBLAS_NUM_THREADS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JULIA_NUM_PRECOMPILE_TASKS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1&#39;</span></span></code></pre></div><p>These variables bound the components individually; an operating-system affinity or CI CPU allocation bounds the whole process tree. The recorded Windows runs used at most four logical CPUs.</p><h2 id="Understand-the-output" tabindex="-1">Understand the output <a class="header-anchor" href="#Understand-the-output" aria-label="Permalink to &quot;Understand the output {#Understand-the-output}&quot;">​</a></h2><p>A run prints a new directory under <code>results/</code>. It contains <code>suite-result.json</code>, a human-readable report, JUnit output and an integrity-checked run bundle. Keep that directory: every interface can reuse its observations. In command examples, replace <code>results/ACTUAL-RUN</code> with the printed directory.</p><p>A successful run means the selected measurements completed and their result checks passed. To fail CI on a slowdown, add a baseline and limits as described in <a href="./../tutorials/comparisons">performance comparisons</a>.</p>`,18)])])}const u=a(n,[["render",r]]);export{k as __pageData,u as default};
